// Renders the security headers generated by the web build (apps/web/out-meta/security-headers.json,
// generate-csp.mjs) as an Nginx include, so Nginx serves exactly the policy the E2E suite tests
// (CM-T066). Runs inside the image build. Refuses names or values Nginx would interpret: a value
// with a quote, backslash, dollar sign (variable expansion) or control character fails the build.
//
//   node infrastructure/nginx/render-security-headers.mjs <security-headers.json> <output.conf>
import { readFileSync, writeFileSync } from 'node:fs';

const [input, output] = process.argv.slice(2);
if (input === undefined || output === undefined) {
  console.error('usage: render-security-headers.mjs <security-headers.json> <output.conf>');
  process.exit(2);
}

/** @type {unknown} */
const parsed = JSON.parse(readFileSync(input, 'utf8'));
if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) throw new Error('expected an object');

const REQUIRED = ['Content-Security-Policy', 'X-Content-Type-Options', 'Referrer-Policy', 'X-Frame-Options'];
const lines = [
  '# Generated at image build time from apps/web/out-meta/security-headers.json. Do not edit.',
  '# Included in every location that serves the static client (add_header is not inherited',
  '# into a location that sets its own headers).',
];
for (const [name, value] of Object.entries(parsed)) {
  if (!/^[A-Za-z][A-Za-z0-9-]{0,63}$/.test(name)) throw new Error(`refusing header name ${JSON.stringify(name)}`);
  if (typeof value !== 'string' || value === '' || /["\\$\p{Cc}]/u.test(value)) {
    throw new Error(`refusing the value of ${name}`);
  }
  lines.push(`add_header ${name} "${value}" always;`);
}
for (const name of REQUIRED) {
  if (!Object.hasOwn(parsed, name)) throw new Error(`missing ${name}`);
}
writeFileSync(output, `${lines.join('\n')}\n`);
console.log(`rendered ${String(lines.length - 3)} security headers`);
